use std::fmt;
use std::path::PathBuf;

use crate::config::Config;
use crate::git::{Git, GitError};
use crate::ui::run_ui;

#[derive(Debug)]
pub struct AppError {
    pub msg: String,
    pub cause: Option<String>,
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.msg)
    }
}

pub fn run() -> Result<(), AppError> {
    let cwd = std::env::current_dir().map_err(|e| AppError {
        msg: format!("{}", e),
        cause: None,
    })?;
    let repo_root = match find_repo_root(&cwd) {
        Ok(p) => p,
        Err(GitError::NotFound) => {
            return Err(AppError {
                msg: "Git repository not found. Please run inside a Git repository.".into(),
                cause: Some(format!(
                    "could not find repository at '{}'; class=Repository (6); code=NotFound (-3)",
                    "."
                )),
            });
        }
        Err(GitError::Other(e)) => {
            return Err(AppError {
                msg: format!("{}", e),
                cause: None,
            });
        }
    };

    let cfg = Config::load();
    let git = Git::new(repo_root);

    run_ui(&git, &cfg).map_err(|e| AppError {
        msg: format!("{}", e),
        cause: None,
    })
}

pub fn find_repo_root(start: &std::path::Path) -> Result<PathBuf, GitError> {
    let mut cur = start.to_path_buf();
    loop {
        let dotgit = cur.join(".git");
        if dotgit.exists() {
            return Ok(cur);
        }
        if !cur.pop() {
            return Err(GitError::NotFound);
        }
    }
}
