use std::fs;
use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct Config {
    pub auto_refresh: bool,
    pub refresh_interval: u64,
    pub auto_fetch: bool,
    pub fetch_interval: u64,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            auto_refresh: true,
            refresh_interval: 10,
            auto_fetch: true,
            fetch_interval: 60,
        }
    }
}

impl Config {
    pub fn load() -> Self {
        let mut cfg = Config::default();
        if let Some(home) = std::env::var_os("HOME") {
            let path: PathBuf = PathBuf::from(home).join(".config/keifu/config.toml");
            if let Ok(s) = fs::read_to_string(&path) {
                parse_toml(&s, &mut cfg);
            }
        }
        if cfg.refresh_interval < 1 {
            cfg.refresh_interval = 1;
        }
        if cfg.fetch_interval < 10 {
            cfg.fetch_interval = 10;
        }
        cfg
    }
}

/// Very small ad-hoc TOML parser for the small config format we support.
fn parse_toml(text: &str, cfg: &mut Config) {
    let mut section = String::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if line.starts_with('[') && line.ends_with(']') {
            section = line[1..line.len() - 1].trim().to_string();
            continue;
        }
        if let Some(eq) = line.find('=') {
            let key = line[..eq].trim();
            let mut value = line[eq + 1..].trim().to_string();
            if let Some(i) = value.find('#') {
                value.truncate(i);
                value = value.trim().to_string();
            }
            let full = if section.is_empty() {
                key.to_string()
            } else {
                format!("{}.{}", section, key)
            };
            match full.as_str() {
                "refresh.auto_refresh" => {
                    if let Some(b) = parse_bool(&value) {
                        cfg.auto_refresh = b;
                    }
                }
                "refresh.refresh_interval" => {
                    if let Ok(n) = value.parse::<u64>() {
                        cfg.refresh_interval = n;
                    }
                }
                "refresh.auto_fetch" => {
                    if let Some(b) = parse_bool(&value) {
                        cfg.auto_fetch = b;
                    }
                }
                "refresh.fetch_interval" => {
                    if let Ok(n) = value.parse::<u64>() {
                        cfg.fetch_interval = n;
                    }
                }
                _ => {}
            }
        }
    }
}

fn parse_bool(s: &str) -> Option<bool> {
    match s {
        "true" => Some(true),
        "false" => Some(false),
        _ => None,
    }
}
