use std::fmt;
use std::path::{Path, PathBuf};
use std::process::Command;

#[derive(Debug)]
pub enum GitError {
    NotFound,
    Other(String),
}

impl fmt::Display for GitError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            GitError::NotFound => write!(f, "repository not found"),
            GitError::Other(e) => write!(f, "{}", e),
        }
    }
}

#[derive(Debug, Clone)]
pub struct CommitInfo {
    pub hash: String,
    pub short_hash: String,
    pub parents: Vec<String>,
    pub author: String,
    pub email: String,
    pub date: String,
    pub subject: String,
    pub body: String,
}

#[derive(Debug, Clone)]
pub struct BranchRef {
    pub name: String,
    pub target: String,
    pub is_remote: bool,
    pub is_head: bool,
}

#[derive(Debug, Clone)]
pub struct FileChange {
    pub status: char,
    pub path: String,
    pub additions: u32,
    pub deletions: u32,
}

pub struct Git {
    pub root: PathBuf,
}

impl Git {
    pub fn new(root: PathBuf) -> Self {
        Self { root }
    }

    fn run(&self, args: &[&str]) -> Result<String, String> {
        let out = Command::new("git")
            .args(args)
            .current_dir(&self.root)
            .output()
            .map_err(|e| format!("git: {}", e))?;
        if !out.status.success() {
            return Err(String::from_utf8_lossy(&out.stderr).to_string());
        }
        Ok(String::from_utf8_lossy(&out.stdout).to_string())
    }

    pub fn current_branch(&self) -> Option<String> {
        let s = self.run(&["symbolic-ref", "--short", "HEAD"]).ok()?;
        let t = s.trim();
        if t.is_empty() {
            None
        } else {
            Some(t.to_string())
        }
    }

    pub fn head_hash(&self) -> Option<String> {
        let s = self.run(&["rev-parse", "HEAD"]).ok()?;
        Some(s.trim().to_string())
    }

    pub fn branches(&self) -> Vec<BranchRef> {
        let head = self.head_hash().unwrap_or_default();
        let mut refs = Vec::new();
        if let Ok(out) = self.run(&[
            "for-each-ref",
            "--format=%(refname)|%(objectname)",
            "refs/heads",
            "refs/remotes",
        ]) {
            for line in out.lines() {
                let parts: Vec<&str> = line.splitn(2, '|').collect();
                if parts.len() != 2 {
                    continue;
                }
                let refname = parts[0];
                let target = parts[1].to_string();
                let (name, is_remote) = if let Some(rest) = refname.strip_prefix("refs/heads/") {
                    (rest.to_string(), false)
                } else if let Some(rest) = refname.strip_prefix("refs/remotes/") {
                    if rest.ends_with("/HEAD") {
                        continue;
                    }
                    (rest.to_string(), true)
                } else {
                    continue;
                };
                let is_head = !is_remote && target == head && Some(&name) == self.current_branch().as_ref();
                refs.push(BranchRef {
                    name,
                    target,
                    is_remote,
                    is_head,
                });
            }
        }
        refs
    }

    pub fn commits(&self, limit: usize) -> Vec<CommitInfo> {
        // Get commits reachable from all branches, with limit
        let fmt = "--pretty=format:%H%x01%h%x01%P%x01%an%x01%ae%x01%ad%x01%s%x01%b%x02";
        let date = "--date=format:%Y-%m-%d %H:%M:%S";
        let args = vec![
            "log".to_string(),
            "--all".to_string(),
            format!("--max-count={}", limit),
            fmt.to_string(),
            date.to_string(),
        ];
        let argrefs: Vec<&str> = args.iter().map(|s| s.as_str()).collect();
        let out = match self.run(&argrefs) {
            Ok(s) => s,
            Err(_) => return Vec::new(),
        };
        let mut commits = Vec::new();
        for rec in out.split('\x02') {
            let rec = rec.trim_start_matches('\n');
            if rec.is_empty() {
                continue;
            }
            let parts: Vec<&str> = rec.splitn(8, '\x01').collect();
            if parts.len() < 7 {
                continue;
            }
            let parents: Vec<String> = if parts[2].is_empty() {
                Vec::new()
            } else {
                parts[2].split_whitespace().map(String::from).collect()
            };
            commits.push(CommitInfo {
                hash: parts[0].to_string(),
                short_hash: parts[1].to_string(),
                parents,
                author: parts[3].to_string(),
                email: parts[4].to_string(),
                date: parts[5].to_string(),
                subject: parts[6].to_string(),
                body: parts.get(7).map(|s| s.to_string()).unwrap_or_default(),
            });
        }
        commits
    }

    pub fn changed_files(&self, commit: &str) -> Vec<FileChange> {
        let args = vec![
            "show".to_string(),
            "--numstat".to_string(),
            "--format=".to_string(),
            commit.to_string(),
        ];
        let argrefs: Vec<&str> = args.iter().map(|s| s.as_str()).collect();
        let numstat_out = self.run(&argrefs).unwrap_or_default();
        let args2 = vec![
            "show".to_string(),
            "--name-status".to_string(),
            "--format=".to_string(),
            commit.to_string(),
        ];
        let argrefs2: Vec<&str> = args2.iter().map(|s| s.as_str()).collect();
        let name_out = self.run(&argrefs2).unwrap_or_default();

        let mut status_map = std::collections::HashMap::new();
        for line in name_out.lines() {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }
            let mut iter = line.split('\t');
            let st = iter.next().unwrap_or("");
            let path = iter.next().unwrap_or("");
            if let Some(c) = st.chars().next() {
                status_map.insert(path.to_string(), c);
            }
        }
        let mut files = Vec::new();
        for line in numstat_out.lines() {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }
            let mut iter = line.split('\t');
            let a = iter.next().unwrap_or("0");
            let d = iter.next().unwrap_or("0");
            let p = iter.next().unwrap_or("").to_string();
            if a == "-" || d == "-" {
                continue; // binary
            }
            let add: u32 = a.parse().unwrap_or(0);
            let del: u32 = d.parse().unwrap_or(0);
            let status = status_map.get(&p).copied().unwrap_or('M');
            files.push(FileChange {
                status,
                path: p,
                additions: add,
                deletions: del,
            });
            if files.len() >= 50 {
                break;
            }
        }
        files
    }

    pub fn has_uncommitted(&self) -> bool {
        match self.run(&["status", "--porcelain"]) {
            Ok(s) => s.lines().any(|l| !l.starts_with("??") && !l.is_empty()),
            Err(_) => false,
        }
    }

    pub fn checkout(&self, target: &str) -> Result<(), String> {
        self.run(&["checkout", target]).map(|_| ())
    }

    pub fn create_branch(&self, name: &str, target: &str) -> Result<(), String> {
        self.run(&["branch", name, target]).map(|_| ())
    }

    pub fn delete_branch(&self, name: &str) -> Result<(), String> {
        self.run(&["branch", "-D", name]).map(|_| ())
    }

    pub fn fetch(&self) -> Result<(), String> {
        self.run(&["fetch", "origin"]).map(|_| ())
    }

    pub fn repo_name(&self) -> String {
        self.root
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or("")
            .to_string()
    }
}

#[allow(dead_code)]
pub fn dir_has_git(p: &Path) -> bool {
    p.join(".git").exists()
}
