//! Raw-mode terminal I/O using libc (via ioctl & termios syscalls through nix-less stdlib).

use std::io::{self, Read, Write};
use std::mem::MaybeUninit;
use std::os::fd::{AsRawFd, RawFd};

#[repr(C)]
#[derive(Copy, Clone)]
pub struct Termios {
    pub c_iflag: u32,
    pub c_oflag: u32,
    pub c_cflag: u32,
    pub c_lflag: u32,
    pub c_line: u8,
    pub c_cc: [u8; 32],
    pub c_ispeed: u32,
    pub c_ospeed: u32,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct WinSize {
    pub ws_row: u16,
    pub ws_col: u16,
    pub ws_xpixel: u16,
    pub ws_ypixel: u16,
}

extern "C" {
    fn tcgetattr(fd: RawFd, termios: *mut Termios) -> i32;
    fn tcsetattr(fd: RawFd, optional_actions: i32, termios: *const Termios) -> i32;
    fn ioctl(fd: RawFd, req: u64, ...) -> i32;
}

// Linux/amd64 values
const TCSANOW: i32 = 0;
const TIOCGWINSZ: u64 = 0x5413;

// Input flags
const IGNBRK: u32 = 0o0000001;
const BRKINT: u32 = 0o0000002;
const PARMRK: u32 = 0o0000010;
const ISTRIP: u32 = 0o0000040;
const INLCR: u32 = 0o0000100;
const IGNCR: u32 = 0o0000200;
const ICRNL: u32 = 0o0000400;
const IXON: u32 = 0o0002000;

// Output flags
const OPOST: u32 = 0o0000001;

// Control flags
const CSIZE: u32 = 0o0000060;
const PARENB: u32 = 0o0000400;
const CS8: u32 = 0o0000060;

// Local flags
const ECHO: u32 = 0o0000010;
const ECHONL: u32 = 0o0000100;
const ICANON: u32 = 0o0000002;
const ISIG: u32 = 0o0000001;
const IEXTEN: u32 = 0o0100000;

// VMIN/VTIME
const VMIN: usize = 6;
const VTIME: usize = 5;

pub struct RawMode {
    original: Termios,
    fd: RawFd,
}

impl RawMode {
    pub fn enable() -> io::Result<Self> {
        let stdin = io::stdin();
        let fd = stdin.as_raw_fd();
        let mut orig = MaybeUninit::<Termios>::uninit();
        let rc = unsafe { tcgetattr(fd, orig.as_mut_ptr()) };
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }
        let orig = unsafe { orig.assume_init() };
        let mut t = orig;
        t.c_iflag &= !(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
        t.c_oflag &= !OPOST;
        t.c_cflag &= !(CSIZE | PARENB);
        t.c_cflag |= CS8;
        t.c_lflag &= !(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
        t.c_cc[VMIN] = 0;
        t.c_cc[VTIME] = 0;
        let rc = unsafe { tcsetattr(fd, TCSANOW, &t) };
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }
        // Enable alternate screen and hide cursor
        let mut out = io::stdout();
        out.write_all(b"\x1b[?1049h")?;
        out.write_all(b"\x1b[?25l")?;
        out.flush()?;
        Ok(RawMode { original: orig, fd })
    }
}

impl Drop for RawMode {
    fn drop(&mut self) {
        let mut out = io::stdout();
        let _ = out.write_all(b"\x1b[?25h");
        let _ = out.write_all(b"\x1b[?1049l");
        let _ = out.flush();
        unsafe {
            tcsetattr(self.fd, TCSANOW, &self.original);
        }
    }
}

pub fn size() -> (u16, u16) {
    let stdout = io::stdout();
    let fd = stdout.as_raw_fd();
    let mut ws = WinSize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    unsafe {
        ioctl(fd, TIOCGWINSZ, &mut ws);
    }
    if ws.ws_col == 0 {
        ws.ws_col = 80;
    }
    if ws.ws_row == 0 {
        ws.ws_row = 24;
    }
    (ws.ws_col, ws.ws_row)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Key {
    Char(char),
    Enter,
    Esc,
    Backspace,
    Tab,
    ShiftTab,
    Up,
    Down,
    Left,
    Right,
    Home,
    End,
    PageUp,
    PageDown,
    Ctrl(char),
    Alt(char),
    Unknown,
}

pub fn read_key(timeout_ms: u64) -> io::Result<Option<Key>> {
    let mut stdin = io::stdin();
    let fd = stdin.as_raw_fd();
    // Use poll for timeout
    if !poll_stdin(fd, timeout_ms)? {
        return Ok(None);
    }
    let mut buf = [0u8; 32];
    let n = stdin.read(&mut buf)?;
    if n == 0 {
        return Ok(None);
    }
    Ok(Some(parse_key(&buf[..n])))
}

fn parse_key(b: &[u8]) -> Key {
    if b.is_empty() {
        return Key::Unknown;
    }
    match b[0] {
        0x1b => {
            if b.len() == 1 {
                return Key::Esc;
            }
            if b[1] == b'[' {
                // CSI
                match b.get(2).copied() {
                    Some(b'A') => return Key::Up,
                    Some(b'B') => return Key::Down,
                    Some(b'C') => return Key::Right,
                    Some(b'D') => return Key::Left,
                    Some(b'H') => return Key::Home,
                    Some(b'F') => return Key::End,
                    Some(b'Z') => return Key::ShiftTab,
                    Some(b'1') | Some(b'2') | Some(b'3') | Some(b'4') | Some(b'5') | Some(b'6') | Some(b'7') | Some(b'8') => {
                        // find final
                        let mut i = 2;
                        while i < b.len() && b[i] != b'~' {
                            i += 1;
                        }
                        let mid = std::str::from_utf8(&b[2..i]).unwrap_or("");
                        match mid {
                            "1" | "7" => return Key::Home,
                            "4" | "8" => return Key::End,
                            "5" => return Key::PageUp,
                            "6" => return Key::PageDown,
                            _ => return Key::Unknown,
                        }
                    }
                    _ => return Key::Unknown,
                }
            } else if b[1] == b'O' {
                match b.get(2).copied() {
                    Some(b'H') => return Key::Home,
                    Some(b'F') => return Key::End,
                    _ => return Key::Unknown,
                }
            } else {
                // Alt+char
                if let Ok(s) = std::str::from_utf8(&b[1..]) {
                    if let Some(c) = s.chars().next() {
                        return Key::Alt(c);
                    }
                }
                return Key::Unknown;
            }
        }
        b'\r' | b'\n' => return Key::Enter,
        b'\t' => return Key::Tab,
        0x7f | 0x08 => return Key::Backspace,
        c if c < 0x20 => {
            let ch = (c + b'a' - 1) as char;
            return Key::Ctrl(ch);
        }
        _ => {}
    }
    if let Ok(s) = std::str::from_utf8(b) {
        if let Some(c) = s.chars().next() {
            return Key::Char(c);
        }
    }
    Key::Unknown
}

#[repr(C)]
struct PollFd {
    fd: RawFd,
    events: i16,
    revents: i16,
}

extern "C" {
    fn poll(fds: *mut PollFd, nfds: u64, timeout: i32) -> i32;
}

const POLLIN: i16 = 0x0001;

fn poll_stdin(fd: RawFd, timeout_ms: u64) -> io::Result<bool> {
    let mut pfd = PollFd {
        fd,
        events: POLLIN,
        revents: 0,
    };
    let rc = unsafe { poll(&mut pfd, 1, timeout_ms as i32) };
    if rc < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(rc > 0 && (pfd.revents & POLLIN) != 0)
}
