#[derive(Debug)]
pub struct UiError(pub String);

impl fmt::Display for UiError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

enum Mode {
    Normal,
    Help,
    Search,
    Input(InputKind),
    Confirm(String, ConfirmKind),
    Message(String),
}

#[derive(Clone)]
enum InputKind {
    CreateBranch,
}

#[derive(Clone)]
enum ConfirmKind {
    DeleteBranch(String),
}

struct AppState<'a> {
    git: &'a Git,
    #[allow(dead_code)]
    cfg: &'a Config,
    commits: Vec<CommitInfo>,
    branches: Vec<BranchRef>,
    current_branch: Option<String>,
    selected: usize,
    scroll: usize,
    mode: Mode,
    search_query: String,
    search_sel: usize,
    input_buf: String,
    width: u16,
    height: u16,
    files_cache_hash: String,
    files: Vec<FileChange>,
    uncommitted: bool,
    /// Branch index selected inside current commit (for h/l navigation).
    branch_sel_idx: usize,
    repo_name: String,
}

impl<'a> AppState<'a> {
    fn new(git: &'a Git, cfg: &'a Config) -> Self {
        Self {
            git,
            cfg,
            commits: Vec::new(),
            branches: Vec::new(),
            current_branch: None,
            selected: 0,
            scroll: 0,
            mode: Mode::Normal,
            search_query: String::new(),
            search_sel: 0,
            input_buf: String::new(),
            width: 80,
            height: 24,
            files_cache_hash: String::new(),
            files: Vec::new(),
            uncommitted: false,
            branch_sel_idx: 0,
            repo_name: git.repo_name(),
        }
    }

    fn refresh(&mut self) {
        self.commits = self.git.commits(500);
        self.branches = self.git.branches();
        self.current_branch = self.git.current_branch();
        self.uncommitted = self.git.has_uncommitted();
        if self.selected >= self.total_rows() {
            self.selected = self.total_rows().saturating_sub(1);
        }
        self.refresh_files();
    }

    fn refresh_files(&mut self) {
        if let Some(c) = self.current_commit() {
            if c.hash != self.files_cache_hash {
                self.files = self.git.changed_files(&c.hash);
                self.files_cache_hash = c.hash.clone();
            }
        } else {
            self.files.clear();
            self.files_cache_hash.clear();
        }
    }

    fn total_rows(&self) -> usize {
        let mut n = self.commits.len();
        if self.uncommitted {
            n += 1;
        }
        n
    }

    fn current_commit_idx(&self) -> Option<usize> {
        let offset = if self.uncommitted { 1 } else { 0 };
        if self.selected < offset {
            return None;
        }
        Some(self.selected - offset)
    }

    fn current_commit(&self) -> Option<&CommitInfo> {
        self.current_commit_idx().and_then(|i| self.commits.get(i))
    }

    fn branches_at_commit(&self, hash: &str) -> Vec<&BranchRef> {
        self.branches.iter().filter(|b| b.target == hash).collect()
    }
}

fn handle_key(app: &mut AppState, key: Key) -> bool {
    match &app.mode {
        Mode::Normal => match key {
            Key::Char('q') | Key::Esc => return false,
            Key::Char('j') | Key::Down => move_selection(app, 1),
            Key::Char('k') | Key::Up => move_selection(app, -1),
            Key::Char('g') | Key::Home => {
                app.selected = 0;
                app.scroll = 0;
                app.branch_sel_idx = 0;
                app.refresh_files();
            }
            Key::Char('G') | Key::End => {
                app.selected = app.total_rows().saturating_sub(1);
                app.branch_sel_idx = 0;
                app.refresh_files();
            }
            Key::Ctrl('d') => move_selection(app, (app.height as i32) / 2),
            Key::Ctrl('u') => move_selection(app, -(app.height as i32) / 2),
            Key::Char('h') | Key::Left => {
                if app.branch_sel_idx > 0 {
                    app.branch_sel_idx -= 1;
                }
            }
            Key::Char('l') | Key::Right => {
                if let Some(c) = app.current_commit() {
                    let n = app.branches_at_commit(&c.hash).len();
                    if n > 0 && app.branch_sel_idx + 1 < n {
                        app.branch_sel_idx += 1;
                    }
                }
            }
            Key::Tab | Key::Char(']') => jump_to_branch(app, 1),
            Key::ShiftTab | Key::Char('[') => jump_to_branch(app, -1),
            Key::Char('@') => {
                if let Some(head) = &app.current_branch.clone() {
                    jump_to_branch_named(app, head);
                }
            }
            Key::Char('?') => {
                app.mode = Mode::Help;
            }
            Key::Char('/') => {
                app.mode = Mode::Search;
                app.search_query.clear();
                app.search_sel = 0;
            }
            Key::Char('R') => {
                app.refresh();
            }
            Key::Char('f') => {
                let _ = app.git.fetch();
                app.mode = Mode::Message("Fetched from origin.".into());
                app.refresh();
            }
            Key::Char('b') => {
                app.mode = Mode::Input(InputKind::CreateBranch);
                app.input_buf.clear();
            }
            Key::Char('d') => {
                if let Some(c) = app.current_commit() {
                    let branches: Vec<String> = app
                        .branches_at_commit(&c.hash)
                        .iter()
                        .filter(|b| !b.is_remote && !b.is_head)
                        .map(|b| b.name.clone())
                        .collect();
                    let idx = app.branch_sel_idx.min(branches.len().saturating_sub(1));
                    if let Some(n) = branches.get(idx) {
                        let name = n.clone();
                        app.mode = Mode::Confirm(
                            format!("Delete branch '{}'? (y/n)", name),
                            ConfirmKind::DeleteBranch(name),
                        );
                    }
                }
            }
            Key::Enter => {
                if let Some(c) = app.current_commit() {
                    let branches_at: Vec<&BranchRef> = app.branches_at_commit(&c.hash);
                    let target = if let Some(b) = branches_at.get(app.branch_sel_idx) {
                        b.name.clone()
                    } else {
                        c.hash.clone()
                    };
                    let _ = app.git.checkout(&target);
                    app.refresh();
                }
            }
            _ => {}
        },
        Mode::Help => match key {
            Key::Char('q') | Key::Esc | Key::Char('?') => {
                app.mode = Mode::Normal;
            }
            _ => {}
        },
        Mode::Search => match key {
            Key::Esc => {
                app.mode = Mode::Normal;
                app.search_query.clear();
            }
            Key::Backspace => {
                if app.search_query.is_empty() {
                    app.mode = Mode::Normal;
                } else {
                    app.search_query.pop();
                    app.search_sel = 0;
                }
            }
            Key::Up | Key::Ctrl('k') => {
                if app.search_sel > 0 {
                    app.search_sel -= 1;
                }
            }
            Key::Down | Key::Ctrl('j') => {
                app.search_sel += 1;
            }
            Key::Enter => {
                let results = search_results(app);
                if let Some(name) = results.get(app.search_sel) {
                    let n = (*name).clone();
                    jump_to_branch_named(app, &n);
                }
                app.mode = Mode::Normal;
                app.search_query.clear();
            }
            Key::Char(c) => {
                app.search_query.push(c);
                app.search_sel = 0;
            }
            _ => {}
        },
        Mode::Input(_k) => match key {
            Key::Esc => {
                app.mode = Mode::Normal;
                app.input_buf.clear();
            }
            Key::Backspace => {
                app.input_buf.pop();
            }
            Key::Enter => {
                let name = app.input_buf.trim().to_string();
                if !name.is_empty() {
                    if let Some(c) = app.current_commit() {
                        let hash = c.hash.clone();
                        let _ = app.git.create_branch(&name, &hash);
                        app.refresh();
                    }
                }
                app.mode = Mode::Normal;
                app.input_buf.clear();
            }
            Key::Char(c) => {
                app.input_buf.push(c);
            }
            _ => {}
        },
        Mode::Confirm(_msg, k) => {
            let k = k.clone();
            match key {
                Key::Char('y') | Key::Char('Y') => {
                    match k {
                        ConfirmKind::DeleteBranch(name) => {
                            let _ = app.git.delete_branch(&name);
                        }
                    }
                    app.refresh();
                    app.mode = Mode::Normal;
                }
                Key::Esc | Key::Char('n') | Key::Char('N') | Key::Char('q') => {
                    app.mode = Mode::Normal;
                }
                _ => {}
            }
        }
        Mode::Message(_) => match key {
            _ => {
                app.mode = Mode::Normal;
            }
        },
    }
    true
}

fn move_selection(app: &mut AppState, delta: i32) {
    let n = app.total_rows();
    if n == 0 {
        return;
    }
    let sel = app.selected as i32 + delta;
    let sel = sel.clamp(0, n as i32 - 1) as usize;
    app.selected = sel;
    app.branch_sel_idx = 0;
    app.refresh_files();
}

fn jump_to_branch(app: &mut AppState, dir: i32) {
    if app.commits.is_empty() {
        return;
    }
    let mut idx = app.selected as i32;
    let total = app.total_rows() as i32;
    loop {
        idx += dir;
        if idx < 0 || idx >= total {
            return;
        }
        if let Some(c) = app.commits.get(idx as usize - if app.uncommitted {1} else {0}) {
            if !app.branches_at_commit(&c.hash).is_empty() {
                app.selected = idx as usize;
                app.branch_sel_idx = 0;
                app.refresh_files();
                return;
            }
        }
    }
}

fn jump_to_branch_named(app: &mut AppState, name: &str) {
    let target_hash = app.branches.iter().find(|b| b.name == name).map(|b| b.target.clone());
    if let Some(h) = target_hash {
        if let Some(i) = app.commits.iter().position(|c| c.hash == h) {
            let offset = if app.uncommitted { 1 } else { 0 };
            app.selected = i + offset;
            app.refresh_files();
            // set branch_sel_idx to the position of `name` in branches_at_commit
            let c = app.commits[i].clone();
            let at = app.branches_at_commit(&c.hash);
            if let Some(idx) = at.iter().position(|b| b.name == name) {
                app.branch_sel_idx = idx;
            }
        }
    }
}

fn search_results<'a>(app: &'a AppState) -> Vec<&'a String> {
    let q = app.search_query.to_lowercase();
    let mut out: Vec<&String> = Vec::new();
    for b in &app.branches {
        if b.name.to_lowercase().contains(&q) {
            out.push(&b.name);
        }
    }
    out
}

// ==== Rendering ====

struct Screen {
    buf: String,
}

impl Screen {
    fn new() -> Self {
        Self {
            buf: String::with_capacity(16 * 1024),
        }
    }

    fn clear(&mut self) {
        self.buf.clear();
        self.buf.push_str("\x1b[2J");
        self.buf.push_str("\x1b[H");
    }

    fn goto(&mut self, x: u16, y: u16) {
        use std::fmt::Write;
        let _ = write!(self.buf, "\x1b[{};{}H", y + 1, x + 1);
    }

    fn fg(&mut self, color: u8) {
        use std::fmt::Write;
        let _ = write!(self.buf, "\x1b[38;5;{}m", color);
    }

    fn reset(&mut self) {
        self.buf.push_str("\x1b[0m");
    }

    fn bold(&mut self) {
        self.buf.push_str("\x1b[1m");
    }

    fn inv(&mut self) {
        self.buf.push_str("\x1b[7m");
    }

    fn put(&mut self, s: &str) {
        self.buf.push_str(s);
    }

    fn flush(&mut self) -> io::Result<()> {
        let mut out = io::stdout();
        out.write_all(self.buf.as_bytes())?;
        out.flush()
    }
}

fn render(app: &mut AppState) -> Result<(), UiError> {
    let mut s = Screen::new();
    s.clear();
    let w = app.width;
    let h = app.height;
    // Top area: commits (takes ~60% height). Bottom: detail + changed files side by side, then status bar last.
    let status_h = 1;
    let bottom_h = 15.min(h.saturating_sub(status_h + 4));
    let commits_h = h.saturating_sub(bottom_h + status_h);

    draw_commits(&mut s, app, 0, 0, w, commits_h);
    let detail_w = w / 2;
    let files_w = w - detail_w;
    draw_detail(&mut s, app, 0, commits_h, detail_w, bottom_h);
    draw_files(&mut s, app, detail_w, commits_h, files_w, bottom_h);
    draw_status(&mut s, app, 0, h - 1, w);

    match &app.mode {
        Mode::Help => draw_help_popup(&mut s, w, h),
        Mode::Search => draw_search_popup(&mut s, app, w, h),
        Mode::Input(_) => draw_input_popup(&mut s, app, w, h),
        Mode::Confirm(msg, _) => draw_message_popup(&mut s, msg, w, h),
        Mode::Message(msg) => draw_message_popup(&mut s, msg, w, h),
        Mode::Normal => {}
    }

    s.reset();
    s.flush().map_err(|e| UiError(format!("{}", e)))
}

fn draw_box(s: &mut Screen, x: u16, y: u16, w: u16, h: u16, title: &str) {
    if w < 2 || h < 2 {
        return;
    }
    // Top
    s.goto(x, y);
    s.put("┌");
    let title_display = if title.is_empty() { String::new() } else { format!(" {} ", title) };
    s.put(&title_display);
    let used = 1 + display_width(&title_display);
    for _ in used..(w as usize - 1) {
        s.put("─");
    }
    s.put("┐");
    // Sides
    for row in 1..h - 1 {
        s.goto(x, y + row);
        s.put("│");
        s.goto(x + w - 1, y + row);
        s.put("│");
    }
    // Bottom
    s.goto(x, y + h - 1);
    s.put("└");
    for _ in 0..(w as usize - 2) {
        s.put("─");
    }
    s.put("┘");
}

fn display_width(s: &str) -> usize {
    // Treat each char as width 1 for ASCII, and try to be sensible about unicode.
    s.chars().count()
}

fn draw_commits(s: &mut Screen, app: &mut AppState, x: u16, y: u16, w: u16, h: u16) {
    draw_box(s, x, y, w, h, "Commits");
    if w < 4 || h < 2 {
        return;
    }
    let inner_w = w as usize - 2;
    let inner_h = (h as usize).saturating_sub(2);

    let layout = layout(&app.commits);
    // Build list of display rows: first optional uncommitted, then commits
    let total = app.total_rows();
    // Ensure scroll keeps selected visible
    if app.selected < app.scroll {
        app.scroll = app.selected;
    }
    if app.selected >= app.scroll + inner_h {
        app.scroll = app.selected + 1 - inner_h;
    }
    let start = app.scroll;
    let end = (start + inner_h).min(total);

    for (row_pos, idx) in (start..end).enumerate() {
        let y_row = y + 1 + row_pos as u16;
        s.goto(x + 1, y_row);
        let is_selected = idx == app.selected;
        if is_selected {
            s.inv();
        }
        // Build row content
        let mut line = String::new();
        let offset = if app.uncommitted { 1 } else { 0 };
        if app.uncommitted && idx == 0 {
            line.push(' ');
            line.push('◯');
            line.push(' ');
            line.push_str(" uncommitted changes");
        } else {
            let c_idx = idx - offset;
            // Graph
            if let Some(row) = layout.rows.get(c_idx) {
                line.push(' ');
                for (i, cell) in row.cells.iter().enumerate() {
                    // Apply color only if not selected (ANSI colors inside inv may be odd)
                    if !is_selected {
                        let col = row.colors[i];
                        line.push_str(&format!("\x1b[38;5;{}m{}\x1b[39m", col, cell));
                    } else {
                        line.push_str(cell);
                    }
                }
                // pad to max cols
                for _ in row.cells.len()..layout.max_cols {
                    line.push(' ');
                }
                line.push(' ');
            }
            if let Some(c) = app.commits.get(c_idx) {
                // Branch labels
                let branches = app.branches_at_commit(&c.hash);
                let is_head_commit = app.current_branch.as_deref()
                    .map(|cb| branches.iter().any(|b| b.name == cb && !b.is_remote))
                    .unwrap_or(false);
                let dot = if is_head_commit { "◉" } else { "●" };
                // Replace last appended commit dot ● with ◉ if head
                if is_head_commit {
                    // Actually we already put ● in the graph; Easiest: ignore and just put label.
                    // For simplicity, prepend dot display here? Skip correction.
                    let _ = dot;
                }

                if !branches.is_empty() {
                    let sel = app.branch_sel_idx.min(branches.len() - 1);
                    let selected_name = &branches[sel].name;
                    let label = if branches.len() == 1 {
                        format!("[{}]", selected_name)
                    } else {
                        format!("[{} +{}]", selected_name, branches.len() - 1)
                    };
                    line.push_str(&format!("\x1b[1;33m{}\x1b[22;39m ", label));
                }
                // Subject, date, author, hash
                let subject = c.subject.clone();
                let date_part = c.date.split_whitespace().next().unwrap_or("").to_string();
                let right = format!("{:10}  {:8}  {}", date_part, truncate(&c.author, 8), c.short_hash);
                // Fit within inner_w
                let right_w = display_width(&right);
                let cur_plain = strip_ansi(&line);
                let cur_w = display_width(&cur_plain);
                let avail = inner_w.saturating_sub(cur_w + right_w + 2);
                let subject_trunc = truncate(&subject, avail);
                line.push_str(&subject_trunc);
                let cur_plain2 = strip_ansi(&line);
                let cur_w2 = display_width(&cur_plain2);
                let pad = inner_w.saturating_sub(cur_w2 + right_w);
                for _ in 0..pad {
                    line.push(' ');
                }
                line.push_str(&right);
            }
        }
        // Pad to full inner width
        let plain = strip_ansi(&line);
        let disp = display_width(&plain);
        let mut padded = line;
        if disp < inner_w {
            for _ in 0..(inner_w - disp) {
                padded.push(' ');
            }
        }
        s.put(&padded);
        if is_selected {
            s.reset();
        }
    }
}

fn draw_detail(s: &mut Screen, app: &AppState, x: u16, y: u16, w: u16, h: u16) {
    draw_box(s, x, y, w, h, "Commit Detail");
    if w < 4 || h < 3 {
        return;
    }
    let inner_w = w as usize - 2;
    let mut lines: Vec<String> = Vec::new();
    if let Some(c) = app.current_commit() {
        lines.push(format!("Commit: {}", c.hash));
        lines.push(format!("Author: {} <{}>", c.author, c.email));
        lines.push(format!("Date:   {}", c.date));
        for (i, p) in c.parents.iter().enumerate() {
            let label = if i == 0 { "Parent" } else { "Parent" };
            lines.push(format!("{}: {}", label, &p[..7.min(p.len())]));
        }
        lines.push(String::new());
        for l in c.subject.lines() {
            lines.push(l.to_string());
        }
        if !c.body.is_empty() {
            lines.push(String::new());
            for l in c.body.lines() {
                lines.push(l.to_string());
            }
        }
    }
    for (i, l) in lines.iter().enumerate().take(h as usize - 2) {
        s.goto(x + 1, y + 1 + i as u16);
        let t = truncate(l, inner_w);
        let mut padded = t;
        let disp = display_width(&padded);
        if disp < inner_w {
            for _ in 0..(inner_w - disp) {
                padded.push(' ');
            }
        }
        s.put(&padded);
    }
}

fn draw_files(s: &mut Screen, app: &AppState, x: u16, y: u16, w: u16, h: u16) {
    draw_box(s, x, y, w, h, "Changed Files");
    if w < 4 || h < 3 {
        return;
    }
    let inner_w = w as usize - 2;
    let mut lines: Vec<String> = Vec::new();
    let total_add: u32 = app.files.iter().map(|f| f.additions).sum();
    let total_del: u32 = app.files.iter().map(|f| f.deletions).sum();
    lines.push(format!("{} files changed  +{} -{}", app.files.len(), total_add, total_del));
    lines.push(String::new());
    for f in &app.files {
        lines.push(format!(" {} {} +{} -{}", f.status, f.path, f.additions, f.deletions));
    }
    for (i, l) in lines.iter().enumerate().take(h as usize - 2) {
        s.goto(x + 1, y + 1 + i as u16);
        let t = truncate(l, inner_w);
        let mut padded = t;
        let disp = display_width(&padded);
        if disp < inner_w {
            for _ in 0..(inner_w - disp) {
                padded.push(' ');
            }
        }
        s.put(&padded);
    }
}

fn draw_status(s: &mut Screen, app: &AppState, x: u16, y: u16, w: u16) {
    s.goto(x, y);
    s.reset();
    let branch = app.current_branch.clone().unwrap_or_default();
    let right_label = match &app.mode {
        Mode::Help => "HELP",
        Mode::Input(_) => "INPUT",
        Mode::Search => "INPUT",
        _ => "",
    };
    let left = match &app.mode {
        Mode::Help => format!(" {}   {}   Esc/q close help", app.repo_name, branch),
        Mode::Search => format!(" {}   {}   Enter confirm  Esc cancel", app.repo_name, branch),
        Mode::Input(_) => format!(" {}   {}   Enter confirm  Esc cancel", app.repo_name, branch),
        _ => format!(
            " {}   {}   j/k move  Enter checkout  b branch  f fetch  ? help  q quit",
            app.repo_name, branch
        ),
    };
    let left_d = display_width(&left);
    let right_len = display_width(right_label);
    let mid = if (left_d + right_len) < w as usize {
        " ".repeat(w as usize - left_d - right_len)
    } else {
        String::new()
    };
    s.put(&left);
    s.put(&mid);
    s.put(right_label);
}

fn draw_help_popup(s: &mut Screen, w: u16, h: u16) {
    let pw = (w as i32 - 10).max(40) as u16;
    let ph = (h as i32 - 6).max(10) as u16;
    let px = (w - pw) / 2;
    let py = (h - ph) / 2;
    draw_box(s, px, py, pw, ph, "Help");
    let lines = help_text();
    let inner_w = pw as usize - 2;
    for (i, l) in lines.iter().enumerate().take(ph as usize - 2) {
        s.goto(px + 1, py + 1 + i as u16);
        let t = truncate(l, inner_w);
        let mut padded = t;
        let disp = display_width(&padded);
        if disp < inner_w {
            for _ in 0..(inner_w - disp) {
                padded.push(' ');
            }
        }
        s.put(&padded);
    }
}

fn draw_search_popup(s: &mut Screen, app: &AppState, w: u16, h: u16) {
    let pw = (w as i32 - 20).max(40) as u16;
    let ph = 10;
    let px = (w - pw) / 2;
    let py = (h - ph) / 2;
    draw_box(s, px, py, pw, ph, "Search branches");
    s.goto(px + 1, py + 1);
    let line = format!("  {}_", app.search_query);
    s.put(&truncate(&line, pw as usize - 2));
    s.goto(px + 1, py + 2);
    let mut sep = String::new();
    for _ in 0..(pw as usize - 2) {
        sep.push('─');
    }
    s.put(&sep);
    let results = search_results(app);
    for (i, n) in results.iter().enumerate().take(ph as usize - 5) {
        s.goto(px + 1, py + 3 + i as u16);
        let sel = i == app.search_sel;
        let marker = if sel { "▶" } else { " " };
        let line = format!("{} {}", marker, n);
        s.put(&truncate(&line, pw as usize - 2));
    }
    s.goto(px + 1, py + ph - 2);
    s.put("  ↑↓: select  Enter: jump  Esc: cancel");
}

fn draw_input_popup(s: &mut Screen, app: &AppState, w: u16, h: u16) {
    let pw = 50.min(w);
    let ph = 5;
    let px = (w - pw) / 2;
    let py = (h - ph) / 2;
    draw_box(s, px, py, pw, ph, "New branch name");
    s.goto(px + 2, py + 2);
    let line = format!("{}_", app.input_buf);
    s.put(&truncate(&line, pw as usize - 4));
}

fn draw_message_popup(s: &mut Screen, msg: &str, w: u16, h: u16) {
    let pw = (msg.chars().count() as u16 + 6).min(w);
    let ph = 5;
    let px = (w - pw) / 2;
    let py = (h - ph) / 2;
    draw_box(s, px, py, pw, ph, "");
    s.goto(px + 2, py + 2);
    s.put(&truncate(msg, pw as usize - 4));
}

