    let mut columns: Vec<Option<String>> = Vec::new();
    let mut rows: Vec<GraphRow> = Vec::new();
    let mut commit_row_index: Vec<usize> = Vec::with_capacity(commits.len());

    for (i, c) in commits.iter().enumerate() {
        // Find the column expecting this commit.
        let mut col = columns.iter().position(|s| s.as_deref() == Some(c.hash.as_str()));
        if col.is_none() {
            let idx = columns.iter().position(|x| x.is_none());
            match idx {
                Some(i) => {
                    columns[i] = Some(c.hash.clone());
                    col = Some(i);
                }
                None => {
                    columns.push(Some(c.hash.clone()));
                    col = Some(columns.len() - 1);
                }
            }
        }
        let commit_col = col.unwrap();

        // Find duplicate columns pointing at the same hash — these converge here.
        let dup_cols: Vec<usize> = columns
            .iter()
            .enumerate()
            .filter_map(|(idx, s)| {
                if idx != commit_col && s.as_deref() == Some(c.hash.as_str()) {
                    Some(idx)
                } else {
                    None
                }
            })
            .collect();

        // Build the commit row
        let width = columns.len();
        let mut cells = vec![" ".to_string(); width];
        let mut colors = vec![0u8; width];
        for (idx, slot) in columns.iter().enumerate() {
            if slot.is_some() && idx != commit_col && !dup_cols.contains(&idx) {
                cells[idx] = "│".to_string();
                colors[idx] = color_for(idx);
            }
        }
        cells[commit_col] = "●".to_string();
        colors[commit_col] = color_for(commit_col);

        // Apply merge indicators for extra parents (beyond the first)
        let extra_parents: Vec<String> = c.parents.iter().skip(1).cloned().collect();

        // Reserve columns for each extra parent
        let mut extra_parent_cols: Vec<usize> = Vec::new();
        for p in &extra_parents {
            // Place extra parent columns to the right of commit col, in order.
            if let Some(i) = columns.iter().position(|s| s.as_deref() == Some(p.as_str())) {
                extra_parent_cols.push(i);
            } else if let Some(i) = columns.iter().position(|x| x.is_none()) {
                columns[i] = Some(p.clone());
                // extend cells/colors if needed
                while cells.len() < columns.len() {
                    cells.push(" ".to_string());
                    colors.push(0);
                }
                cells[i] = "╮".to_string();
                colors[i] = color_for(i);
                extra_parent_cols.push(i);
            } else {
                columns.push(Some(p.clone()));
                cells.push("╮".to_string());
                colors.push(color_for(columns.len() - 1));
                extra_parent_cols.push(columns.len() - 1);
            }
        }

