        if !extra_parent_cols.is_empty() {
            for &pc in &extra_parent_cols {
                if pc > commit_col {
                    for k in commit_col + 1..pc {
                        if cells[k] == " " {
                            cells[k] = "─".to_string();
                            colors[k] = color_for(commit_col);
                        }
                    }
                    cells[pc] = "╮".to_string();
                    colors[pc] = color_for(pc);
                }
            }
