            let mut ccolors = vec![0u8; columns.len()];
            for (idx, slot) in columns.iter().enumerate() {
                if slot.is_some() && idx != commit_col && !dup_cols.contains(&idx) {
                    ccells[idx] = "│".to_string();
                    ccolors[idx] = color_for(idx);
                }
