            let max_dc = *dup_cols.iter().max().unwrap();
            ccells[commit_col] = if commit_col < min_dc || commit_col > max_dc {
                "├".to_string()
            } else {
                "├".to_string()
            };
            ccolors[commit_col] = color_for(commit_col);
            for &d in &dup_cols {
                if d > commit_col {
                    for k in commit_col + 1..d {
                        if ccells[k] == " " {
                            ccells[k] = "─".to_string();
                            ccolors[k] = color_for(commit_col);
                        }
                    }
                    ccells[d] = "╯".to_string();
                    ccolors[d] = color_for(d);
                } else if d < commit_col {
                    for k in d + 1..commit_col {
                        if ccells[k] == " " {
                            ccells[k] = "─".to_string();
                            ccolors[k] = color_for(commit_col);
                        }
                    }
                    ccells[d] = "╰".to_string();
                    ccolors[d] = color_for(d);
                }
            }
            rows.push(GraphRow {
                cells: ccells,
                colors: ccolors,
                commit_col,
                commit_idx: None,
            });
            for &d in &dup_cols {
                columns[d] = None;
            }
        }

        // Update columns for next iteration: the commit column now waits for the first parent.
        if let Some(first) = c.parents.first() {
            columns[commit_col] = Some(first.clone());
        } else {
            columns[commit_col] = None;
        }

        // Trim trailing Nones
        while matches!(columns.last(), Some(None)) {
            columns.pop();
        }
    }

    let max_cols = rows.iter().map(|r| r.cells.len()).max().unwrap_or(0);
    GraphLayout {
        rows,
        commit_row_index,
        max_cols,
    }
}
