        let mut extra_parent_cols: Vec<usize> = Vec::new();
        for p in &extra_parents {
            // Place extra parent columns to the right of commit col, in order.
            if let Some(i) = columns.iter().position(|s| s.as_deref() == Some(p.as_str())) {
                extra_parent_cols.push(i);
            } else if let Some(i) = columns.iter().position(|x| x.is_none()) {
                columns[i] = Some(p.clone());
                // extend cells/colors if needed
                while cells.len() < columns.len() {
                    cells.push(" ".to_string());
                    colors.push(0);
                }
                cells[i] = "╮".to_string();
                colors[i] = color_for(i);
                extra_parent_cols.push(i);
            } else {
                columns.push(Some(p.clone()));
                cells.push("╮".to_string());
                colors.push(color_for(columns.len() - 1));
                extra_parent_cols.push(columns.len() - 1);
            }
        }

        // For each extra parent column to the right of commit_col, fill ─ in between
        if !extra_parent_cols.is_empty() {
            for &pc in &extra_parent_cols {
                if pc > commit_col {
                    for k in commit_col + 1..pc {
                        if cells[k] == " " {
                            cells[k] = "─".to_string();
                            colors[k] = color_for(commit_col);
                        }
                    }
                    cells[pc] = "╮".to_string();
                    colors[pc] = color_for(pc);
                }
            }
        }

        commit_row_index.push(rows.len());
        rows.push(GraphRow {
            cells: cells.clone(),
            colors: colors.clone(),
            commit_col,
            commit_idx: Some(i),
        });

        // If there were duplicate (converging) columns, emit a connector row merging them.
        if !dup_cols.is_empty() {
            let mut ccells = vec![" ".to_string(); columns.len()];
            let mut ccolors = vec![0u8; columns.len()];
            for (idx, slot) in columns.iter().enumerate() {
                if slot.is_some() && idx != commit_col && !dup_cols.contains(&idx) {
                    ccells[idx] = "│".to_string();
                    ccolors[idx] = color_for(idx);
                }
            }
            // commit_col gets ├ or │ depending on direction
            let min_dc = *dup_cols.iter().min().unwrap();
            let max_dc = *dup_cols.iter().max().unwrap();
            ccells[commit_col] = if commit_col < min_dc || commit_col > max_dc {
                "├".to_string()
            } else {
                "├".to_string()
            };
            ccolors[commit_col] = color_for(commit_col);
            for &d in &dup_cols {
                if d > commit_col {
                    for k in commit_col + 1..d {
                        if ccells[k] == " " {
                            ccells[k] = "─".to_string();
                            ccolors[k] = color_for(commit_col);
                        }
                    }
                    ccells[d] = "╯".to_string();
                    ccolors[d] = color_for(d);
                } else if d < commit_col {
                    for k in d + 1..commit_col {
                        if ccells[k] == " " {
                            ccells[k] = "─".to_string();
                            ccolors[k] = color_for(commit_col);
                        }
                    }
                    ccells[d] = "╰".to_string();
                    ccolors[d] = color_for(d);
                }
            }
            rows.push(GraphRow {
                cells: ccells,
                colors: ccolors,
                commit_col,
                commit_idx: None,
            });
            for &d in &dup_cols {
                columns[d] = None;
            }
        }

        // Update columns for next iteration: the commit column now waits for the first parent.
        if let Some(first) = c.parents.first() {
            columns[commit_col] = Some(first.clone());
        } else {
            columns[commit_col] = None;
        }

        // Trim trailing Nones
        while matches!(columns.last(), Some(None)) {
            columns.pop();
        }
    }

    let max_cols = rows.iter().map(|r| r.cells.len()).max().unwrap_or(0);
    GraphLayout {
        rows,
        commit_row_index,
        max_cols,
    }
}
