//! Compute graph rendering for a commit list (git-log-like graph).
//!
//! The graph is rendered with each column being 2 characters wide:
//! position 0 is the column's glyph (commit dot or │ track), position 1 is
//! a horizontal connector (─) or space.

use crate::git::CommitInfo;

#[derive(Debug, Clone)]
pub struct GraphRow {
    /// Pairs of (glyph, connector) indexed by column.
    pub cells: Vec<(String, String)>,
    pub colors: Vec<u8>,
    pub connector_colors: Vec<u8>,
    pub commit_col: usize,
    pub commit_idx: Option<usize>,
}

pub struct GraphLayout {
    pub rows: Vec<GraphRow>,
    pub commit_row_index: Vec<usize>,
    pub max_cols: usize,
}

pub fn color_for(col: usize) -> u8 {
    let palette = [11u8, 12, 13, 14, 10, 9];
    palette[col % palette.len()]
}

pub fn layout(commits: &[CommitInfo]) -> GraphLayout {
    let mut columns: Vec<Option<String>> = Vec::new();
    let mut rows: Vec<GraphRow> = Vec::new();
    let mut commit_row_index: Vec<usize> = Vec::with_capacity(commits.len());

    for (i, c) in commits.iter().enumerate() {
        // Allocate/find column for this commit.
        let mut col = columns.iter().position(|s| s.as_deref() == Some(c.hash.as_str()));
        if col.is_none() {
            let idx = columns.iter().position(|x| x.is_none());
            match idx {
                Some(i) => {
                    columns[i] = Some(c.hash.clone());
                    col = Some(i);
                }
                None => {
                    columns.push(Some(c.hash.clone()));
                    col = Some(columns.len() - 1);
                }
            }
        }
        let commit_col = col.unwrap();

        // Duplicate columns awaiting this hash (branches converging).
        let dup_cols: Vec<usize> = columns
            .iter()
            .enumerate()
            .filter_map(|(idx, s)| {
                if idx != commit_col && s.as_deref() == Some(c.hash.as_str()) {
                    Some(idx)
                } else {
                    None
                }
            })
            .collect();

        let width = columns.len();
        let mut cells: Vec<(String, String)> = vec![(" ".into(), " ".into()); width];
        let mut colors = vec![0u8; width];
        let mut cconn = vec![0u8; width];
        for (idx, slot) in columns.iter().enumerate() {
            if slot.is_some() && idx != commit_col && !dup_cols.contains(&idx) {
                cells[idx].0 = "│".to_string();
                colors[idx] = color_for(idx);
            }
        }
        cells[commit_col].0 = "●".to_string();
        colors[commit_col] = color_for(commit_col);

